// AUDIT ROUND 8 (long-seeds): salted copy of tests/review_crash_writeback.rs, generated by
// scratchpad/audit8-long-seeds/mk_salted.py. 6 seed site(s) XORed with
// AUDIT8_SALT (0 = the committed seeds). Do not edit; not part of the suite.
//! `CrashableBacking` must not be more lenient than Linux writeback after a
//! failed `fdatasync`; durability tests are only as strong as this model.
//!
//! - A failed `fdatasync` only reports that *some* writeback failed. Pages
//!   the flusher wrote earlier, or that the failing sync wrote before the
//!   page that failed, may already be on disk. Its dirty bytes are therefore
//!   *maybe persisted*, not lost: a later power loss can keep any subset of
//!   them, whole or torn. A retried sync still has nothing dirty to write,
//!   so they never become certain on their own (F01).
//! - The kernel writes back whole cached pages. After a failed writeback the
//!   page stays cached (clean) with the unpersisted bytes; a later write
//!   anywhere in the same page re-dirties it, and the next successful sync
//!   persists the entire cached page, bytes of the failed sync included.
//! - Bytes that a later successful sync replaced or truncated are never
//!   brought back by an older failed writeback.

use std::collections::BTreeSet;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;

use maki_backing::Backing;
use maki_test_support::crash_backing::{CrashableBacking, FaultOp};
use rand::rngs::StdRng;
use rand::SeedableRng;

/// The page size of the model's page cache.
const PAGE: usize = 4096;
const SEEDS: u64 = 256;

fn fail_next_sync(backing: &CrashableBacking) {
    let armed = Arc::new(AtomicBool::new(true));
    backing.set_fault_hook(Some(Arc::new(move |op| match op {
        FaultOp::SyncData { .. } if armed.swap(false, Ordering::SeqCst) => {
            Some(std::io::Error::other("injected writeback EIO"))
        }
        _ => None,
    })));
}

fn read_all(backing: &CrashableBacking, path: &str) -> Vec<u8> {
    let file = backing.open(path, false).unwrap();
    let mut bytes = vec![0; file.len().unwrap() as usize];
    file.read_at(0, &mut bytes).unwrap();
    bytes
}

/// A published file of `len` durable zero bytes.
fn durable_zeros(len: usize) -> CrashableBacking {
    let backing = CrashableBacking::new();
    let file = backing.open("f", true).unwrap();
    file.write_at(0, &vec![0; len]).unwrap();
    file.sync_data().unwrap();
    backing.sync_dir("").unwrap();
    backing
}

#[test]
fn pending_writes_follow_each_inodes_writeback() {
    let backing = CrashableBacking::new();
    let a = backing.open("a", true).unwrap();
    let b = backing.open("b", true).unwrap();
    a.set_len(4).unwrap();
    a.write_at(0, b"").unwrap();
    a.punch_hole(4, 1).unwrap();
    assert_eq!(backing.pending_write_count(), 0);

    a.punch_hole(0, 1).unwrap();
    b.write_at(0, b"b").unwrap();
    assert_eq!(backing.pending_write_count(), 2);
    a.sync_data().unwrap();
    assert_eq!(backing.pending_write_count(), 1);
    b.sync_data().unwrap();
    assert_eq!(backing.pending_write_count(), 0);
    assert_eq!(backing.write_count_since_crash(), 2);

    for lenient in [false, true] {
        backing.set_lenient_sync_failures(lenient);
        b.write_at(0, b"c").unwrap();
        fail_next_sync(&backing);
        assert!(b.sync_data().is_err());
        assert_eq!(backing.pending_write_count(), usize::from(lenient));
        b.sync_data().unwrap();
        assert_eq!(backing.pending_write_count(), 0);
    }
    assert_eq!(backing.write_count_since_crash(), 4);
    b.write_at(0, b"d").unwrap();
    backing.crash_all_lost();
    assert_eq!(backing.pending_write_count(), 0);
    assert_eq!(backing.write_count_since_crash(), 0);
}

/// Two dirty pages whose sync fails: a power loss may keep either, both or
/// neither, and the page cache keeps showing both.
#[test]
fn bytes_of_a_failed_sync_may_survive_a_power_loss() {
    let mut seen = BTreeSet::new();
    for seed in 0..SEEDS {
        let backing = durable_zeros(2 * PAGE);
        let file = backing.open("f", false).unwrap();
        file.write_at(0, &[1; PAGE]).unwrap();
        file.write_at(PAGE as u64, &[2; PAGE]).unwrap();
        fail_next_sync(&backing);
        assert!(file.sync_data().is_err());
        backing.set_fault_hook(None);
        assert_eq!(read_all(&backing, "f")[..PAGE], [1; PAGE]);
        drop(file);

        backing.crash(&mut StdRng::seed_from_u64(crate::a8_salt() ^ seed));
        let bytes = read_all(&backing, "f");
        assert_eq!(bytes.len(), 2 * PAGE, "seed {seed}");
        let page0 = bytes[..PAGE].iter().all(|b| *b == 1);
        let page1 = bytes[PAGE..].iter().all(|b| *b == 2);
        assert!(
            page0 || bytes[..PAGE].iter().all(|b| *b == 0),
            "seed {seed}: page 0 is neither old nor new"
        );
        assert!(
            page1 || bytes[PAGE..].iter().all(|b| *b == 0),
            "seed {seed}: page 1 is neither old nor new"
        );
        seen.insert((page0, page1));
    }
    assert_eq!(
        seen.len(),
        4,
        "a failed sync must leave every subset of its pages possibly on disk: {seen:?}"
    );
}

/// A retried sync has nothing dirty to write: the bytes are not made
/// certain (the worst case still loses them), but they stay possible.
#[test]
fn a_retried_sync_leaves_failed_writeback_possible_but_not_certain() {
    let setup = || {
        let backing = CrashableBacking::new();
        let file = backing.open("f", true).unwrap();
        file.write_at(0, b"old").unwrap();
        file.sync_data().unwrap();
        backing.sync_dir("").unwrap();
        file.write_at(0, b"new").unwrap();
        fail_next_sync(&backing);
        assert!(file.sync_data().is_err());
        backing.set_fault_hook(None);
        file.sync_data().unwrap();
        backing
    };
    let backing = setup();
    backing.crash_all_lost();
    assert_eq!(read_all(&backing, "f"), b"old");

    let mut seen = BTreeSet::new();
    for seed in 0..SEEDS {
        let backing = setup();
        backing.crash(&mut StdRng::seed_from_u64(crate::a8_salt() ^ seed));
        seen.insert(read_all(&backing, "f"));
    }
    assert_eq!(
        seen,
        BTreeSet::from([b"old".to_vec(), b"new".to_vec()]),
        "a retried sync must neither persist nor rule out the failed writeback"
    );
}

/// With tearing, a write of a failed sync can survive in part, at sector
/// granularity, like any other unsynced write.
#[test]
fn a_failed_sync_can_leave_a_torn_write_on_disk() {
    let mut torn = 0;
    for seed in 0..SEEDS {
        let backing = durable_zeros(PAGE).with_tearing(512);
        let file = backing.open("f", false).unwrap();
        file.write_at(0, &[7; PAGE]).unwrap();
        fail_next_sync(&backing);
        assert!(file.sync_data().is_err());
        backing.set_fault_hook(None);
        drop(file);

        backing.crash(&mut StdRng::seed_from_u64(crate::a8_salt() ^ seed));
        let bytes = read_all(&backing, "f");
        for sector in bytes.chunks(512) {
            assert!(
                sector.iter().all(|b| *b == 7) || sector.iter().all(|b| *b == 0),
                "seed {seed}: a sector mixes old and new bytes"
            );
        }
        if bytes.contains(&7) && bytes.contains(&0) {
            torn += 1;
        }
    }
    assert!(torn > 0, "no crash kept part of the failed sync's write");
}

/// Re-dirtying a page and syncing it persists the whole cached page,
/// including the bytes of the failed sync in that page. A page that was not
/// re-dirtied keeps its failed bytes uncertain.
#[test]
fn a_successful_sync_writes_every_redirtied_page_whole() {
    let backing = durable_zeros(2 * PAGE);
    let file = backing.open("f", false).unwrap();
    file.write_at(0, b"AAAA").unwrap();
    file.write_at(PAGE as u64, b"BBBB").unwrap();
    fail_next_sync(&backing);
    assert!(file.sync_data().is_err());
    backing.set_fault_hook(None);

    // Same page as AAAA, different bytes.
    file.write_at(8, b"CCCC").unwrap();
    file.sync_data().unwrap();
    drop(file);

    backing.crash_all_lost();
    let bytes = read_all(&backing, "f");
    assert_eq!(
        &bytes[..12],
        b"AAAA\0\0\0\0CCCC",
        "the kernel writes back the whole cached page, not only the later write"
    );
    assert_eq!(
        &bytes[PAGE..PAGE + 4],
        b"\0\0\0\0",
        "a page that was not re-dirtied must not become certain"
    );
}

/// Overwriting the failed bytes and syncing makes the new bytes durable;
/// no crash may bring the older failed writeback back on top of them.
#[test]
fn an_older_failed_writeback_never_overwrites_a_later_durable_write() {
    for seed in 0..SEEDS {
        let backing = durable_zeros(2 * PAGE).with_tearing(512);
        let file = backing.open("f", false).unwrap();
        file.write_at(0, &[1; 2 * PAGE]).unwrap();
        fail_next_sync(&backing);
        assert!(file.sync_data().is_err());
        backing.set_fault_hook(None);
        file.write_at(0, &[2; 100]).unwrap();
        file.sync_data().unwrap();
        file.write_at(PAGE as u64, &[3; 100]).unwrap();
        drop(file);

        backing.crash(&mut StdRng::seed_from_u64(crate::a8_salt() ^ seed));
        let bytes = read_all(&backing, "f");
        assert!(
            bytes[..100].iter().all(|b| *b == 2),
            "seed {seed}: an older failed writeback replaced durable bytes"
        );
        assert!(
            bytes[100..PAGE].iter().all(|b| *b == 1),
            "seed {seed}: the synced page is the whole cached page"
        );
    }
}

/// A truncation that a successful sync made durable removes the failed
/// writeback beyond it for good; growing the file again shows zeros.
#[test]
fn a_durable_truncation_discards_failed_writeback_beyond_it() {
    for seed in 0..SEEDS {
        let backing = durable_zeros(2 * PAGE).with_tearing(512);
        let file = backing.open("f", false).unwrap();
        file.write_at(PAGE as u64, &[9; PAGE]).unwrap();
        fail_next_sync(&backing);
        assert!(file.sync_data().is_err());
        backing.set_fault_hook(None);
        file.set_len(PAGE as u64).unwrap();
        file.sync_data().unwrap();
        file.set_len(2 * PAGE as u64).unwrap();
        drop(file);

        backing.crash(&mut StdRng::seed_from_u64(crate::a8_salt() ^ seed));
        let bytes = read_all(&backing, "f");
        assert!(
            bytes.len() == PAGE || bytes.len() == 2 * PAGE,
            "seed {seed}: length {}",
            bytes.len()
        );
        assert!(
            !bytes.contains(&9),
            "seed {seed}: truncated failed writeback came back"
        );
    }
}

/// A truncation whose sync failed may already be on disk too.
#[test]
fn a_truncation_of_a_failed_sync_may_survive_a_power_loss() {
    let mut lengths = BTreeSet::new();
    for seed in 0..SEEDS {
        let backing = durable_zeros(2 * PAGE);
        let file = backing.open("f", false).unwrap();
        file.set_len(PAGE as u64).unwrap();
        fail_next_sync(&backing);
        assert!(file.sync_data().is_err());
        backing.set_fault_hook(None);
        drop(file);

        backing.crash(&mut StdRng::seed_from_u64(crate::a8_salt() ^ seed));
        lengths.insert(read_all(&backing, "f").len());
    }
    assert_eq!(lengths, BTreeSet::from([PAGE, 2 * PAGE]));
}

/// The kernel writes a page back as the page cache holds it: past
/// end-of-file a cached page is zero. If an earlier truncation whose sync
/// failed is lost, the disk keeps the old length, and the written-back page
/// shows those zeros where the old bytes were; pages not written back keep
/// the old bytes.
#[test]
fn a_written_back_page_is_zero_past_the_cached_end_of_file() {
    let backing = CrashableBacking::new();
    let file = backing.open("f", true).unwrap();
    file.write_at(0, &[0xAA; 2 * PAGE]).unwrap();
    file.sync_data().unwrap();
    backing.sync_dir("").unwrap();
    file.set_len(100).unwrap();
    fail_next_sync(&backing);
    assert!(file.sync_data().is_err());
    backing.set_fault_hook(None);
    file.write_at(0, b"x").unwrap();
    file.sync_data().unwrap();
    drop(file);

    backing.crash_all_lost();
    let bytes = read_all(&backing, "f");
    assert_eq!(bytes.len(), 2 * PAGE, "the failed truncation was lost");
    assert_eq!(bytes[0], b'x');
    assert!(bytes[1..100].iter().all(|b| *b == 0xAA));
    assert!(
        bytes[100..PAGE].iter().all(|b| *b == 0),
        "the written-back page must be the cached page, zero past its end"
    );
    assert!(bytes[PAGE..].iter().all(|b| *b == 0xAA));
}
